function plan({ posts, includes, pageState }) {
  const records = pageState?.records;
  if (!Array.isArray(posts) || !Array.isArray(records))
    throw Error("Invalid search or Airtable response");
  const users = new Map((includes?.users ?? []).map((u) => [String(u.id), u.username])),
    known = new Set(
      records
        .map((r) => r?.fields?.Tweet_id)
        .filter((x) => x !== undefined && x !== null)
        .map(String),
    ),
    pending = [];
  for (const p of posts) {
    if (
      typeof p.id !== "string" ||
      typeof p.text !== "string" ||
      typeof p.createdAt !== "string" ||
      typeof p.publicMetrics?.like_count !== "number"
    )
      throw Error("Missing post ID, text, creation time or like count");
    if (known.has(p.id)) continue;
    const author = users.get(String(p.authorId));
    if (typeof author !== "string" || !author) throw Error("Missing expanded post author");
    const replyId = p.raw?.in_reply_to_user_id,
      reply = replyId == null ? null : users.get(String(replyId));
    if (replyId != null && typeof reply !== "string") throw Error("Missing expanded reply user");
    pending.push({
      fields: {
        Likes: p.publicMetrics?.like_count ?? 0,
        Tweet: p.text,
        Tweet_id: p.id,
        "Tweet URL": "https://twitter.com/" + author + "/status/" + p.id,
        Author: reply,
        Time: p.createdAt,
      },
    });
  }
  return { pending };
}

const search = $("Search recent X posts").first().json;
const posts = (search.data ?? []).map((p) => ({
    id: p.id,
    text: p.text,
    authorId: p.author_id,
    createdAt: p.created_at,
    publicMetrics: p.public_metrics,
    raw: p,
  })),
  records = $input
    .all()
    .map((x) => x.json)
    .filter((x) => x && x.fields);
const p = plan({ posts, includes: search.includes ?? {}, pageState: { records } });
return p.pending.map((x) => ({ json: x.fields, pairedItem: { item: 0 } }));
